const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
let motionPaused=false;
try{motionPaused=localStorage.getItem('sz-motion')==='paused';}catch{}
function syncMotion(){
 const paused=motionPaused||motionQuery.matches;
 document.body.classList.toggle('motion-paused',paused);
 document.body.classList.toggle('motion-hidden',document.hidden);
 $('motion-toggle').setAttribute('aria-pressed',String(paused));
 $('motion-toggle').disabled=motionQuery.matches;
 $('motion-label').textContent=motionQuery.matches?'Reduced motion':paused?'Motion paused':'Motion on';
 $('motion-toggle').title=motionQuery.matches?'Reduced motion follows your device preference':paused?'Resume decorative motion':'Pause decorative motion';
}
document.addEventListener('click',event=>{
 if(!event.target.closest('[data-action=toggle-motion]'))return;
 motionPaused=!motionPaused;
 try{localStorage.setItem('sz-motion',motionPaused?'paused':'on');}catch{}
 syncMotion();
});
motionQuery.addEventListener('change',syncMotion);
document.addEventListener('visibilitychange',syncMotion);
syncMotion();




/* Judge entry point: core fixture now; recorded Qwen evidence and opt-in setup. */
function qwenCaution(){return `<aside class="judge-caution" role="note" id="qwen-judge-caution"><span class="judge-caution-icon" aria-hidden="true">⚠</span><div><h3>Recorded on our machine. Your setup may differ.</h3><p>We tested Qwen using Ollama on OffGrid Dev’s Windows computer. We have not verified it on your machine. No access to our computer or Ollama service is provided. The judge quickstart does not run or download models automatically.</p><p>${judgeModelsLocked()?'Live local inference is disabled for this session.':'A live rerun uses your own local setup and may produce different results.'} ${button('Optional local setup','judge-setup','','text-button')}</p></div></aside>`;}

function renderJudge(){
 const recorded=state.judge?.recorded_target;
 return `<section class="panel judge-session"><div><span class="eyebrow">YOUR LOCAL SESSION</span><h2>You’re connected to Sandbox Zero.</h2><p>Keep the launch window open. Stop with Ctrl+C. Your evaluation records stay in the separate judge workspace.</p></div><div class="judge-key"><label for="judge-access-key">Access key for this session</label><code id="judge-access-key" tabindex="0">${esc(token||'Connect using the key printed in your terminal')}</code>${button('Copy access key','judge-copy-key',!token?'disabled':'','secondary')}<small>This key changes each launch. Keep it private.</small></div></section>
 <section class="panel judge-fixture"><div class="panel-head"><div><span class="eyebrow">01 / RUN THE CORE PROTOTYPE</span><h2>Six probes. Inspect every outcome.</h2><p>Controlled fixtures run on this computer with no API key, model download or Docker setup.</p></div>${button('Run six fixture cases','judge-first','','primary')}</div><div class="panel-body"><div class="judge-path"><span>Red request</span><i aria-hidden="true">→</i><span>Blue checks</span><i aria-hidden="true">→</i><span>Fixture target</span><i aria-hidden="true">→</i><span>Audit record</span></div><div class="detail-links">${button('Inspect Requests','judge-requests')}${button('Verify audit integrity','judge-audit')}${button('Open Proof Studio','proof-open')}</div><p class="muted">Proof Studio signing is optional and needs the cryptography package. The separate CONTAINER_VALIDATION.html file records the Linux VM deployment checks. This local fixture session does not demonstrate container isolation.</p></div></section>
 <section class="panel judge-qwen" id="judge-qwen"><div class="panel-head"><div><span class="eyebrow">02 / SEPARATE RECORDED EXPERIMENT</span><h2>Qwen on the team’s machine</h2><p>Recorded observations, not a live run on this computer.</p></div>${tag('Recorded / 25 Oct 2026','neutral')}</div><div class="panel-body">${qwenCaution()}
 ${recorded?`<div class="judge-recorded-summary"><strong>${esc(recorded.target_calls)} actual generations</strong><span>${esc(recorded.requests)} requests</span><span>${esc(recorded.failed_requests)} failed</span><code>${esc(recorded.model)} / Ollama CPU</code></div>${table(['Fixed input','Defense','Recorded outcome'],recorded.rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.profile)}</td><td>${tag(r.outcome)}</td></tr>`).join(''),'Recorded Qwen results from the team machine')}<p class="muted">${esc(recorded.scope)}</p>${button('Download recorded outcomes','judge-recorded-export','','secondary')}`:'<p class="info-callout warn">The recorded Qwen file is not present in this copy. The fixture demo remains available.</p>'}
 <details class="judge-setup" id="judge-local-setup"><summary>Optional: run Qwen on your own machine</summary><ol><li>Install and open <a href="https://ollama.com/download/windows" target="_blank" rel="noreferrer">Ollama</a>. Its local service uses 127.0.0.1:11434. If it is not running, start <code>ollama serve</code> in a separate terminal.</li><li>Download the target with <code>ollama pull qwen2.5:0.5b</code> (about 398 MB for target weights, plus space for the runtime and optional classifiers).</li><li>In the project folder, prepare the separate Python environment:<pre class="code-block">python -m venv .judge-venv
.\.judge-venv\Scripts\python.exe -m pip install -r requirements-ml.txt -r requirements-proof.txt
.\.judge-venv\Scripts\python.exe setup_models.py</pre>The setup script downloads the pinned Red and Blue models. The comparison needs Blue’s classifier as well as Qwen.</li><li>Stop the current judge server with Ctrl+C. Restart explicitly:<pre class="code-block">.\START_JUDGES.cmd --enable-local-models</pre>The launcher uses .judge-venv when available.</li><li>Open <strong>Local ML lab</strong>, scroll to <strong>Meet the real target</strong>, and click <strong>Run real local target</strong>. Only this explicit action runs the Qwen experiment.</li></ol><p>Compatibility, speed, memory use and responses may differ. Missing dependencies stop the run without a fixture fallback. See JUDGE_GUIDE.md for cross-platform notes and the full setup.</p><p><a href="https://docs.ollama.com/windows" target="_blank" rel="noreferrer">Official Ollama Windows instructions ↗</a> · <a href="https://ollama.com/library/qwen2.5:0.5b" target="_blank" rel="noreferrer">Exact Qwen model ↗</a></p></details></div></section>`;
}

function showJudgeSetup(){
 navigate('judge');const setup=$('judge-local-setup');setup.open=true;setup.scrollIntoView({block:'start'});
}
document.addEventListener('click',async event=>{
 const control=event.target.closest('[data-action]');if(!control||control.disabled)return;
 try{
  if(control.dataset.action==='judge-first'){const id=await run({suite:'quick',profile:'hardened'});if(id)requestRoute('','','current');}
  else if(control.dataset.action==='judge-requests')navigate('requests');
  else if(control.dataset.action==='judge-audit')navigate('audit');
  else if(control.dataset.action==='judge-setup')showJudgeSetup();
  else if(control.dataset.action==='judge-copy-key'){await navigator.clipboard.writeText(token);notify('Access key copied. Keep it private.');}
  else if(control.dataset.action==='judge-recorded-export'&&state.judge?.recorded_target)download('recorded-qwen-demo.json',state.judge.recorded_target);
 }catch(error){notify(control.dataset.action==='judge-copy-key'?'Select and copy the access key shown above.':error.message);}
});
